"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command "@'
import json
from pathlib import Path
source = Path('doc00_records.json.txt').read_text(encoding='utf-8')
q1 = 'In a multicenter, double-blind, placebo-controlled trial, we randomly assigned 4837 patients, 60 through 80 years of age (78% men),'
q2 = 'a margarine supplemented with a combination of EPA and DHA (with a targeted additional daily intake of 400 mg of EPA-DHA), a margarine supplemented with ALA (with a targeted additional daily intake of 2 g of ALA), a margarine supplemented with EPA-DHA and ALA, or a placebo margarine.'
