for q in (q1, q2, q3):
    assert q in source and len(q) < 400
row = json.loads(Path('row.json').read_text(encoding='utf-8-sig'))
def quote(s):
    return {'file': 'doc00_records.json.txt', 'text': s}
out = {'key': row['key'], 'facts': [
    {'fact_id': 'randomized_contrast', 'verdict': 'STATED', 'quotes': [quote(q1), quote(q2)], 'other_trial': False},
    {'fact_id': 'placebo_control', 'verdict': 'STATED', 'quotes': [quote(q3)], 'other_trial': False}
]}
assert [f['fact_id'] for f in out['facts']] == [f['fact_id'] for f in row['facts']]
Path('out.json').write_text(json.dumps(out, ensure_ascii=False, indent=2) + '\\n', encoding='utf-8')
print('out.json written; quote and fact-order checks passed.')
